f="snmplib/read_config.c"
s=open(f).read()
old="""    end = line + strlen(line);
    start_from = line + (cptr - buf) + strlen(cptr) + 1;
    if (start_from > end)
        start_from = end;
    fprintf(stderr,
            "ASSERT_EVT point=root_guard line=%p token_start_offset=%td start_from=%p line_end=%p\\n",
            (void *)line, cptr - buf, (void *)start_from, (void *)end);
    line = skip_white(start_from);
"""
new="""    fprintf(stderr,
            "ASSERT_EVT point=root_guard line=%p token_start_offset=%td start_from=%p line_end=%p\\n",
            (void *)line, cptr - buf, (void *)(line + (cptr - buf) + strlen(cptr) + 1), (void *)(line + strlen(line)));
    line = skip_white(line + (cptr - buf) + strlen(cptr) + 1);
"""
print("old in s:", old in s)
if old in s:
    s=s.replace(old,new)
    open(f,"w").write(s)
    print("patched")
PYEOF
grep -n "skip_white(line + (cptr" snmplib/read_config.c'

